import { type Api } from '../src/api';
import { Chessground } from '../src/chessground';
import type * as cg from '../src/types';

const BOARD_SIZE = 320;
const rect = {
  left: 0,
  top: 0,
  right: BOARD_SIZE,
  bottom: BOARD_SIZE,
  width: BOARD_SIZE,
  height: BOARD_SIZE,
  x: 0,
  y: 0,
  toJSON: () => ({}),
} as DOMRect;

const makeBoard = (config: cg.Config): { api: Api; board: HTMLElement } => {
  const wrap = document.createElement('div');
  wrap.classList.add('cg-wrap');
  wrap.getBoundingClientRect = () => rect;
  document.body.appendChild(wrap);
  const api = Chessground(wrap, config);
  const board = wrap.querySelector('cg-board')!;
  board.getBoundingClientRect = () => rect;
  api.state.dom.bounds.clear();
  return { api, board };
};

const clickSquare = (board: HTMLElement, key: cg.Key): void => {
  const file = key.charCodeAt(0) - 97,
    rank = key.charCodeAt(1) - 49;
  board.dispatchEvent(
    new MouseEvent('mousedown', {
      clientX: (file + 0.5) * (BOARD_SIZE / 8),
      clientY: (7 - rank + 0.5) * (BOARD_SIZE / 8),
      cancelable: true,
    }),
  );
};

test('debug', () => {
  const shape = { orig: 'e2', dest: 'e4', brush: 'red' };
  const { api, board } = makeBoard({
    trustAllEvents: true,
    drawable: { enabled: true, eraseOnMovablePieceClick: true, eraseOnClick: true },
  });
  const s = api.state;
  console.log('config check', {
    enabled: s.drawable.enabled,
    eraseOnClick: s.drawable.eraseOnClick,
    eraseOnMovablePieceClick: s.drawable.eraseOnMovablePieceClick,
  });
  api.setShapes([shape]);
  clickSquare(board, 'a1');
  console.log('after a1', { shapes: s.drawable.shapes.length, selected: s.selected, drag: !!s.draggable.current, drawableCurrent: !!s.drawable.current });
  api.setShapes([shape]);
  console.log('before e2', { shapes: s.drawable.shapes.length, selected: s.selected, drag: !!s.draggable.current, drawableCurrent: !!s.drawable.current });
  clickSquare(board, 'e2');
  console.log('after e2', { shapes: s.drawable.shapes.length, selected: s.selected, drag: !!s.draggable.current, drawableCurrent: !!s.drawable.current });
  api.destroy();
});

