  const shape = { orig: 'e2', dest: 'e4', brush: 'red' };
  const { api, board } = makeBoard({
    trustAllEvents: true,
    drawable: { enabled: true, eraseOnMovablePieceClick: true, eraseOnClick: true },
  });
  const s = api.state;
  const log = (tag: string) =>
    console.log(tag, {
      shapes: s.drawable.shapes.length,
      selected: s.selected,
      drag: !!s.draggable.current,
      drawable: !!s.drawable.current,
      piecesE2: s.pieces.get('e2'),
      piecesA8: s.pieces.get('a8'),
    });
  api.setShapes([shape]);
  clickSquare(board, 'a3');
