  api.setShapes([shape]);
  clickSquare(board, 'e2');
  log('after e2');
  api.selectSquare(null);
  log('after unselect');
  api.setShapes([shape]);
  log('before a8');
  clickSquare(board, 'a8');
  log('after a8');
  api.destroy();
});

